head.script:
scwin.log = function (msg) {
    var prev = txa_log.getValue() || "";
    txa_log.setValue(prev + msg + "\n");
};

scwin.onpageload = function () {
    scwin.log("=== ml_top.xml onpageload ===");
};

// 1) 현재 화면(최상위)의 msgLink 를 공개 API 로 읽기
scwin.btn_self_onclick = function () {
    var list = $p.getMsgLinkList();
    scwin.log("[자기 화면] getMsgLinkList() = " + JSON.stringify(list, null, 2));
};

// 2) includeFrame 자식 화면의 msgLink 를 부모에서 읽기
scwin.btn_inc_onclick = function () {
    var list = inc1.getMsgLinkList();          // includeFrame 컴포넌트에 직접 호출
    scwin.log("[inc1 자식] getMsgLinkList() = " + JSON.stringify(list, null, 2));
};

// 3) linkage id 로 하나만 콕 집어서, 특정 field 값 꺼내기
scwin.btn_pick_onclick = function () {
    var lk = $p.getMsgLink("LK_TOP_1");        // id 로 단건 조회
    scwin.log("[단건] getMsgLink('LK_TOP_1')");
    scwin.log("  type       = " + lk.type);
    scwin.log("  send[0].sfn = " + lk.send[0].sfn);
    scwin.log("  send[1].dfn = " + lk.send[1].dfn);
};
